function createNovelAIVibePreset(id, name) {
  return {
    id,
    name,
    vibes: []
  };
}
function createNovelAIVibePresetSettings(id = DEFAULT_NOVELAI_VIBE_PRESET_ID, name = DEFAULT_NOVELAI_VIBE_PRESET_NAME) {
  const preset = createNovelAIVibePreset(id, name);
  return {
    activePresetId: preset.id,
    presets: [preset]
  };
}

